\begin{tikzpicture}[font=\sffamily, scale=1.0]
  % Axes
  \draw[->, thick] (0,0) -- (7,0) node[anchor=north] {Kinetic energy};
  \draw[->, thick] (0,0) -- (0,5) node[anchor=east, align=right] {Number of\\molecules};

  % Curves
  % T1: taller, narrower peak to the left
  \draw[thick] (0,0) .. controls (1,5.5) and (2,4) .. (6.5,0.2) node[above right] {$T_1$};

  % T2: lower peak, further to the right, longer tail
  \draw[dashed, thick] (0,0) .. controls (1.5,3.2) and (2.8,2.8) .. (6.8,0.5) node[above right] {$T_2$};

  % Activation energy line
  \draw[dashed, thick] (4.8,0) -- (4.8,4.5) node[above] {$E_a$};

  % Caption
  \node at (3.5,-0.8) {Fig. 5.1};
\end{tikzpicture}

\begin{tikzpicture}[font=\sffamily, scale=1.0]
  % Axes
  \draw[->, thick] (0,0) -- (7.5,0) node[anchor=north east] {Kinetic energy};
  \draw[->, thick] (0,0) -- (0,5) node[anchor=east, align=right] {Number of\\molecules};

  % Curves
  % T1: lower temperature -> taller, narrower peak, further to the left
  \draw[thick] (0,0) .. controls (1.2,4.8) and (1.8,4.5) .. (6.5,0.1) node[right] {$T_1$};

  % T2: higher temperature -> lower peak, further to the right, longer tail
  \draw[dashed, thick] (0,0) .. controls (2.2,2.8) and (2.8,2.8) .. (7.0,0.3) node[right] {$T_2$};

  % Activation energy line
  \draw[dashed, thick] (5.2,0) -- (5.2,4.5) node[above] {$E_a$};

  % Caption
  \node at (3.75,-0.8) {Fig. 5.1};
\end{tikzpicture}
